        ("The creation of a Provision for Doubtful Debts is an application of which accounting concept?", ["The Prudence Concept", "The Materiality Concept", "The Money Measurement Concept", "The Realization Concept"], 0, "Prudence requires anticipating potential uncollectible debts so receivables are not overstated on the balance sheet.", "Accounting Concepts"),
        ("In the Trading Account, Gross Profit is calculated as:", ["Net Sales Revenue minus Cost of Goods Sold", "Total Sales minus Operating Expenses", "Net Sales minus Net Purchases", "Total Assets minus Total Liabilities"], 0, "Gross Profit = Sales Revenue - Cost of Goods Sold (Opening Inventory + Net Purchases - Closing Inventory).", "Financial Statements"),
        ("Cost of Goods Sold (COGS) is mathematically determined by:", ["Opening Inventory + Purchases + Carriage Inwards - Closing Inventory", "Opening Inventory + Closing Inventory - Purchases", "Sales Revenue - Operating Expenses", "Purchases minus Sales"], 0, "COGS represents direct manufacturing/procurement costs of inventory sold during the financial period.", "Final Accounts"),
        ("Carriage Inwards (freight cost incurred to transport purchased merchandise into the business warehouse) is:", ["Added to Purchases in the Trading Account to determine Cost of Goods Sold", "Treated as a selling expense in the Profit and Loss Account", "Deducted from Sales", "Classified as a non-current asset"], 0, "Carriage inwards is a direct acquisition cost of inventory included in cost of sales.", "Trading Account"),
        ("Carriage Outwards (delivery costs paid by a business to transport sold goods to customers) is classified as:", ["An operating distribution expense in the Profit and Loss Account", "A direct deduction from Purchases in the Trading Account", "A capital asset on the balance sheet", "A current liability"], 0, "Carriage outwards is a selling and distribution expense incurred after the point of sale.", "Profit and Loss"),
